/**
 * Utility types and helpers for playbook type extraction and dependent output resolution.
 *
 * These utilities are used by:
 * - PlaybookTypes.ts for activity definition inference
 * - PlaybookHelpers.ts for activity function overloads
 */
import type { Column, TableName, Typed, TypeOf } from '@servicenow/sdk-core/db';
import type { ExtractRefTable, OutputFieldWithDotwalk, TableAwareRecordWithFallback } from '@servicenow/sdk-core/flow';
export type AnyTypedEntry = Typed<any, any>;
/**
 * Recursively adds a `_tableName` property to every object in the type tree.
 * Applied to record reference types so users can access `._tableName` to get
 * the platform `.:TN` pill suffix (the table name of the record at this path).
 *
 * Arrays and functions are left unchanged. Primitives are left unchanged.
 * Uses `T extends object` (not `Record`) so interfaces work correctly.
 *
 * Primitive-backed intersections like `boolean & Record<string, FlowValueType>`
 * (produced by BooleanColumn/IntegerColumn outputs) satisfy `T extends object`
 * via their Record component, so we explicitly guard against all TypeScript
 * primitives before the object branch to prevent primitive output types from
 * gaining `_tableName`.
 */
export type WithTableName<T> = T extends readonly any[] ? T : T extends Function ? T : T extends string | boolean | number | bigint | symbol | null | undefined ? T : T extends object ? // biome-ignore lint/suspicious/noExplicitAny: _tableName resolves to DataReference (= any) for pill compatibility
{
    [K in keyof T]: WithTableName<T[K]>;
} & {
    readonly _tableName: any;
} : T;
/** Extract TS types from a map of Typed entries (all optional — for inputs and experience properties) */
export type ActivityEntryTypes<T extends Record<string, AnyTypedEntry> | undefined> = T extends Record<string, AnyTypedEntry> ? {
    [K in keyof T]?: TypeOf<T[K]>;
} : {};
export type PlaybookColumnType<C extends Column> = ExtractRefTable<C> extends never ? TypeOf<C> : WithTableName<TableAwareRecordWithFallback<ExtractRefTable<C>>>;
export type PlaybookColumnTypes<T extends Record<string, Column> | undefined> = T extends Record<string, Column> ? {
    [K in keyof T]: PlaybookColumnType<T[K]>;
} : {};
/** Extract the dependent field name from a Column entry, or never if none */
type ExtractDependent<C> = C extends {
    dependent: infer D;
} ? (D extends string ? D : never) : never;
/**
 * Resolve the table type for a `dependent` Column by looking up its dependent
 * field name in the call-site inputs and extracting the TableName if valid.
 * Shared by dependent input and output resolution.
 */
type ResolveDependentTable<C, Inputs> = ExtractDependent<C> extends keyof Inputs ? Inputs[ExtractDependent<C>] extends TableName ? Inputs[ExtractDependent<C>] : never : never;
/**
 * Resolve a `dependent` record Column (e.g. `DocumentIdColumn`) to a table-aware
 * record reference for the table it depends on. Falls back to the column's base
 * type when that table can't be resolved to a literal `TableName` (the table
 * input is omitted or not a literal), which keeps unknown/unregistered tables
 * permissive. Shared by dependent input and output resolution.
 */
type ResolveDependentRecord<C, Inputs> = ResolveDependentTable<C, Inputs> extends never ? TypeOf<C> : WithTableName<TableAwareRecordWithFallback<ResolveDependentTable<C, Inputs> & TableName>> & Now.Internal.TableBrand<ResolveDependentTable<C, Inputs> & TableName>;
/**
 * Resolve a single output field:
 * - If it has a `dependent` property, resolve it to the dependent table's record
 *   reference (see {@link ResolveDependentRecord}).
 * - If it's a Column (e.g., ReferenceColumn), use OutputFieldWithDotwalk to support
 *   dot-walking on referenced table fields.
 * - Otherwise, extract the standard type via TypeOf.
 */
type ResolveOutputField<C, Inputs> = C extends {
    dependent: string;
} ? ResolveDependentRecord<C, Inputs> : C extends Column ? WithTableName<OutputFieldWithDotwalk<C>> : TypeOf<C>;
/**
 * Resolve all output fields with dependent table awareness.
 * Each field with `dependent` is resolved independently based on its own dependent field,
 * allowing multiple outputs to depend on different input fields.
 * Example:
 * inputs: {
 *     tableName: TableNameColumn({ label: 'Table' }),
 *     otherTable: TableNameColumn({ label: 'Other Table' }),
 * }
 * outputs: {
 *     record: DocumentIdColumn({ dependent: 'tableName' }),      // → typed to tableName's table
 *     otherRecord: DocumentIdColumn({ dependent: 'otherTable' }) // → typed to otherTable's table
 * }
 */
export type ResolveActivityOutputs<Outputs extends Record<string, AnyTypedEntry>, Inputs> = {
    [K in keyof Outputs]: ResolveOutputField<Outputs[K], Inputs>;
};
/**
 * True when a Column's value type is a record reference (a Fluent `Record`,
 * identified by its `table` field) — i.e. a `DocumentIdColumn`. Distinguishes it
 * from a `TemplateValueColumn`, which also carries `dependent` but resolves to
 * template data (no `table` field), so only genuine record inputs are constrained.
 */
type IsRecordColumn<C> = [Extract<TypeOf<C>, {
    table: TableName;
}>] extends [never] ? false : true;
/**
 * True when a value type has a nominal `TableBrand<T>` member (`{ __table__: T }`)
 * — e.g. `ReferenceColumn`'s `TypeOf`, which is
 * `Record<RefTable> | ExplicitKey | TableBrand<RefTable> | string`. A branded
 * member already pins the value to a specific table, so a same-table pill
 * (which carries this brand once resolved through `dataPill()`) is naturally
 * accepted and a wrong-table pill naturally rejected — no widening needed.
 * `DocumentIdColumn`'s `TypeOf` (`Record<TableName> | string`) has no such
 * member, which is what distinguishes it as needing the widen-then-reconstrain
 * treatment in {@link ResolveDependentRecordInputs} / `CapturedInputs`.
 */
export type HasTableBrand<T> = [Extract<T, {
    readonly __table__: string;
}>] extends [never] ? false : true;
/**
 * Constrain dependent record *inputs* to the table selected at the call site.
 *
 * For each raw input Column that is a dependent record reference (e.g. a
 * `DocumentIdColumn({ dependent: 'table_name' })` record input), produce an
 * optional property typed as that table's record reference via the shared
 * {@link ResolveDependentRecord} — so a whole-record pill (e.g.
 * `create.outputs.record`) from a different table is rejected, while one from
 * the matching table is accepted. A raw sys_id `string` is always accepted as an
 * escape hatch. Non-record inputs (including dependent `TemplateValueColumn`
 * fields such as `values`) are omitted here, leaving them unconstrained.
 *
 * Unknown / unregistered tables resolve to `Record<string, unknown>`, which
 * accepts any record — so the table check is strict only for known tables.
 */
export type ResolveDependentRecordInputs<Inputs extends Record<string, AnyTypedEntry>, TInputs> = {
    [K in keyof Inputs as Inputs[K] extends {
        dependent: string;
    } ? IsRecordColumn<Inputs[K]> extends true ? K : never : never]?: string | ResolveDependentRecord<Inputs[K], TInputs>;
};
/**
 * Like `Omit<T, K>`, but distributes over union types instead of collapsing them.
 * Plain `Omit<A | B, K>` computes `Pick<A | B, Exclude<keyof (A|B), K>>`, and since
 * `(A|B)[P]` for a shared key P is `A[P] | B[P]`, this merges the branches into one
 * flat type — losing any discriminated-union exclusivity between A and B. Distributing
 * the `Omit` over each branch first (`T extends any ? Omit<T, K> : never`) preserves it.
 */
export type DistributiveOmit<T, K extends keyof any> = T extends any ? Omit<T, K> : never;
export {};
